package main;
import "std/mem";import "std/io";
struct Pair { a: own[i64]; b: own[i64]; }
fn main() {
  var total: i64 = 0;
  for (var i = 0; i < 1000000; i = i + 1) {
    var p = Pair { a: new[i64](i), b: new[i64](i) };
    total = total + *p.a;
  }
  assert(mem.owner_count() == 0);
  io.println(total);
}

