package main;
import v "std/vector";import "std/io";
fn main() {
  var bytes = v.create[u8]();
  for (var i = 0; i < 500000; i = i + 1) { bytes.append(u8(i % 251)); }
  var sum: i64 = 0;
  unsafe { var it = v.cursor[u8](&bytes); for (var i = 0; i < 500000; i = i + 1) { sum = sum + i64(*v.next[u8](&raw it)); } }
  assert(sum == 62499028);
  bytes.clear();
  io.println(sum);
}

